Here's a simple function that calculates the elapsed time since a post was made, given the post's timestamp in the format `YYYY-MM-DDTHH:mm:ssZ`.

```typescript
import moment from 'moment-timezone';

function elapsedTimeSincePost(postTime: string): string {
  const post = moment.tz(postTime, 'YYYY-MM-DDTHH:mm:ssZ');
  const now = moment.tz('America/Los_Angeles');
  const elapsed = now.diff(post, 'seconds');

  if (elapsed < 60) {
    return `${elapsed} seconds ago`;
  } else if (elapsed < 3600) {
    return `${Math.floor(elapsed / 60)} minutes ago`;
  } else if (elapsed < 86400) {
    return `${Math.floor(elapsed / 3600)} hours ago`;
  } else if (elapsed < 604800) {
    return `${Math.floor(elapsed / 86400)} days ago`;
  } else {
    return `${Math.floor(elapsed / 604800)} weeks ago`;
  }
}
```

