1. First, install the `xlsx` library:

```bash
npm install xlsx
```

2. Create a new file `compareExcel.js` and paste the following code:

```javascript
const XLSX = require('xlsx');

function compareExcelFiles(file1, file2, callback) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet_name_list1 = workbook1.SheetNames;
  const sheet_name_list2 = workbook2.SheetNames;

  const sheetNames = [...new Set([...sheet_name_list1, ...sheet_name_list2])];

  const discrepancies = [];

  sheetNames.forEach(sheetName => {
    const data1 = XLSX.utils.sheet_to_json(workbook1.Sheets[sheetName]);
    const data2 = XLSX.utils.sheet_to_json(workbook2.Sheets[sheetName]);

    const common = data1.filter(row1 => data2.some(row2 => JSON.stringify(row1) === JSON.stringify(row2)));
    const unique1 = data1.filter(row => !common.includes(row));
    const unique2 = data2.filter(row => !common.includes(row));

    if (unique1.length > 0) {
      discrepancies.push({ sheet: sheetName, type: 'unique1', data: unique1 });
    }

    if (unique2.length > 0) {
      discrepancies.push({ sheet: sheetName, type: 'unique2', data: unique2 });
    }
  });

  callback(discrepancies);
}

// Usage
compareExcelFiles('file1.xlsx', 'file2.xlsx', (discrepancies) => {
  console.log(discrepancies);
});
```

This script reads two Excel files, compares the data in each sheet, and returns an array of objects containing the sheet name, type of discrepancy (unique to the first file or the second file), and the data that is unique to each file.

